//! What the about screen says: this build, where its source is, and the
//! licenses of the crates it is made of (`assets/licenses.json`, generated by
//! `just regenerate-licenses`).

use serde::Deserialize;

/// The public repository, from `Cargo.toml`. The AGPL has us offer the source
/// to users: set `repository` there before any release.
pub const REPOSITORY: &str = env!("CARGO_PKG_REPOSITORY");

const LICENSES: &str = include_str!("../assets/licenses.json");

/// The info screen's pages. Only the ones the command line can open: it goes
/// on from there to a single license.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Page {
    About,
    Licenses,
    Logs,
    Debug,
}

/// This build's version, and its commit when known.
pub fn version() -> String {
    let version = env!("CARGO_PKG_VERSION");
    match env!("AIR_DESKTOP_BUILD_COMMIT") {
        "" => version.to_string(),
        commit => format!("{version} ({commit})"),
    }
}

/// Where problems are reported, once there is a public repository: this
/// client's, as Air's own support doesn't look after it.
pub fn issues() -> Option<String> {
    (!REPOSITORY.is_empty()).then(|| format!("{}/issues", REPOSITORY.trim_end_matches('/')))
}

#[derive(Debug, Clone, Deserialize)]
pub struct License {
    pub name: String,
    pub text: String,
    pub used_by: Vec<LicensedCrate>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct LicensedCrate {
    pub name: String,
    pub version: String,
}

/// The dependencies' licenses, by license. Air's own crates aren't among them
/// (cargo-about skips unpublished crates): the about page names them.
pub fn licenses() -> Vec<License> {
    #[derive(Deserialize)]
    struct Licenses {
        licenses: Vec<License>,
    }
    // Checked in, and read by a test: can't fail in a build that passed.
    serde_json::from_str::<Licenses>(LICENSES)
        .map(|file| file.licenses)
        .unwrap_or_else(|err| {
            tracing::error!("the license list doesn't parse: {err}");
            Vec::new()
        })
}

#[cfg(test)]
mod tests {
    use sha2::{Digest as _, Sha256};

    use super::*;

    /// New dependencies must not ship without their licenses listed.
    #[test]
    fn the_license_list_is_of_this_lockfile() {
        let lockfile = include_bytes!("../Cargo.lock");
        let hash: String = Sha256::digest(lockfile)
            .iter()
            .map(|byte| format!("{byte:02x}"))
            .collect();
        assert_eq!(
            hash,
            include_str!("../assets/licenses.lock").trim(),
            "Cargo.lock changed: run `just regenerate-licenses`"
        );
    }

    #[test]
    fn the_license_list_covers_what_we_ship() {
        let licenses = licenses();
        let names: Vec<_> = licenses
            .iter()
            .flat_map(|license| &license.used_by)
            .map(|used| used.name.as_str())
            .collect();
        for name in ["gpui-pre", "tokio", "image", "zbus"] {
            assert!(names.contains(&name), "{name} isn't listed");
        }
        assert!(licenses.iter().all(|license| !license.text.is_empty()));
    }
}
